  (7545170930, 3851),
  (7545018865, 3851),
  (7545011957, 3803),
  (7545096661, 10651),
  (7544967617, 6851),
  (7544855743, 5701),
  (7544896720, 4201),
  (7545055220, 29901),
  (7545096659, 3904),
  (7545064696, 5601),
  (7544967616, 3802),
  (7545170929, 2951),
  (7545064695, 3851),
  (7544855742, 1701),
  (7545055218, 3501)
) as v(deal_lid, contact_lid), public.contacts c
where d.legacy_id = v.deal_lid
  and c.legacy_id = v.contact_lid;

-- E) "Boots" -> "Boots – John Smith" where the dealname was just the company
update public.deals
set dealname = company || ' – ' || contact_name
where legacy_id is not null
  and company is not null
  and contact_name is not null
  and lower(btrim(dealname)) = lower(btrim(company));

-- F) counts + company links follow from the new deal links
update public.deals d
set n_contacts = sub.cnt
from (
  select deal_id, count(*) as cnt
  from public.contacts
  where deal_id is not null
  group by deal_id
) sub
where sub.deal_id = d.id
  and d.n_contacts is distinct from sub.cnt;

update public.contacts c
set company_id = d.company_id
from public.deals d
where c.deal_id = d.id
  and c.company_id is null
  and d.company_id is not null;

commit;
